 function roll(){if(phase!=='turn'||busy)return;busy=true;rollBtn.disabled=true;let p=players[current],n=1+Math.floor(Math.random()*6);setTurnText(`${p.name} rolled a ${n}!`,`Moving ${n} spaces...`);log(`${p.name} rolled a ${n}.`);let step=0;let interval=setInterval(()=>{p.pos=(p.pos+1)%positions.length;step++;renderPlayers();if(step>=n){clearInterval(interval);busy=false;land(p)}},230)}
 function land(p){let t=types[p.pos];if(t==='coin'){let amount=Math.random()<.25?5:3;p.coins+=amount;setTurnText(`+${amount} coins!`,`A little pocket change never hurts.`);log(`${p.name} picked up ${amount} coins.`)}else if(t==='star'){if(p.coins>=20){p.coins-=20;p.stars++;setTurnText('A star is yours!','20 coins well spent.');log(`${p.name} bought a star! ★`)}else{p.coins+=5;setTurnText('Star out of reach!','Not enough coins — take 5 consolation coins.');log(`${p.name} couldn't afford the star. +5 coins.`)}}else{let prize=5+Math.floor(Math.random()*6);p.coins+=prize;setTurnText(`Street event! +${prize}`,['A fan gave you a tip!','Found a stash behind the arcade!','The crowd loves you!'][Math.floor(Math.random()*3)]);log(`${p.name} hit a street event for ${prize} coins.`)}renderPlayers();setTimeout(advanceTurn,1000)}
