 if(!f.ended){let dist=f.b.x-f.a.x;if(dist>112)f.b.x-=72*dt;else if(Math.random()<dt*1.5){f.b.attack=.2;f.a.hp=Math.max(0,f.a.hp-(5+Math.random()*7))}if(f.a.hp<=0||f.b.hp<=0||f.elapsed>35)endFight(f.a.hp>=f.b.hp?'player':'cpu')}
