 function endFight(winner){if(!fight||fight.ended)return;fight.ended=true;lastWinner=winner;let text,reward;if(winner==='player'){players[0].coins+=12;text=`${players[0].name} wins the brawl!`;reward='+12 coins — the crowd is yours.';log(`${players[0].name} won the bonus brawl! +12 coins.`)}else{let bot=fight.foe;bot.coins+=10;text=`${bot.name} takes the win!`;reward=`${bot.name} earns 10 coins. You'll get them next time!`;log(`${bot.name} won the bonus brawl.`)}renderPlayers();byId('winnerText').textContent=text;byId('rewardText').textContent=reward;byId('battleStatus').textContent='KNOCKOUT!';byId('gameover').classList.add('show')}
